 1 | // SPDX-License-Identifier: MIT
 2 | pragma solidity =0.8.17;
 3 | 
 4 | import "forge-std/Script.sol";
 5 | 
 6 | import {Parameters}             from "../../src/params/Parameters.sol";
 7 | import {VaultManagerV2}         from "../../src/core/VaultManagerV2.sol";
 8 | import {DNft}                   from "../../src/core/DNft.sol";
 9 | import {Dyad}                   from "../../src/core/Dyad.sol";
10 | import {Licenser}               from "../../src/core/Licenser.sol";
11 | import {Vault}                  from "../../src/core/Vault.sol";
12 | import {VaultWstEth}            from "../../src/core/Vault.wsteth.sol";
13 | import {IWETH}                  from "../../src/interfaces/IWETH.sol";
14 | import {IAggregatorV3}          from "../../src/interfaces/IAggregatorV3.sol";
15 | import {KerosineManager}        from "../../src/core/KerosineManager.sol";
16 | import {UnboundedKerosineVault} from "../../src/core/Vault.kerosine.unbounded.sol";
17 | import {BoundedKerosineVault}   from "../../src/core/Vault.kerosine.bounded.sol";
18 | import {Kerosine}               from "../../src/staking/Kerosine.sol";
19 | import {KerosineDenominator}    from "../../src/staking/KerosineDenominator.sol";
20 | 
21 | import {ERC20} from "@solmate/src/tokens/ERC20.sol";
22 | 
23 | struct Contracts {
24 |   Kerosine               kerosene;
25 |   Licenser               vaultLicenser;
26 |   VaultManagerV2         vaultManager;
27 |   Vault                  ethVault;
28 |   VaultWstEth            wstEth;
29 |   KerosineManager        kerosineManager;
30 |   UnboundedKerosineVault unboundedKerosineVault;
31 |   BoundedKerosineVault   boundedKerosineVault;
32 |   KerosineDenominator    kerosineDenominator;
33 | }
34 | 
35 | contract DeployV2 is Script, Parameters {
36 |   function run() public returns (Contracts memory) {
37 |     vm.startBroadcast();  // ----------------------
38 | 
39 |     Licenser vaultLicenser = new Licenser();
40 | 
41 |     // Vault Manager needs to be licensed through the Vault Manager Licenser
42 |     VaultManagerV2 vaultManager = new VaultManagerV2(
43 |       DNft(MAINNET_DNFT),
44 |       Dyad(MAINNET_DYAD),
45 |       vaultLicenser
46 |     );
47 | 
48 |     // weth vault
49 |     Vault ethVault = new Vault(
50 |       vaultManager,
51 |       ERC20        (MAINNET_WETH),
52 |       IAggregatorV3(MAINNET_WETH_ORACLE)
53 |     );
54 | 
55 |     // wsteth vault
